class Solution {
public:
    long long maximumTotalCost(vector<int>& nums) {
        long long pos = nums[0];
        long long neg = -1e18;
        for (size_t i = 1; i < nums.size(); ++i) {
            long long new_pos = max(pos, neg) + nums[i];
            long long new_neg = pos - nums[i];
            pos = new_pos;
            neg = new_neg;
        }
        return max(pos, neg);
    }
};

class Solution {
    public long maximumTotalCost(int[] nums) {
        long pos = nums[0];
        long neg = (long) -1e18;
        for (int i = 1; i < nums.length; ++i) {
            long newPos = Math.max(pos, neg) + nums[i];
            long newNeg = pos - nums[i];
            pos = newPos;
            neg = newNeg;
        }
        return Math.max(pos, neg);
    }
}

var maximumTotalCost = function(nums) {
    let pos = BigInt(nums[0]);
    let neg = -1000000000000000000n;
    for (let i = 1; i < nums.length; ++i) {
        const x = BigInt(nums[i]);
        const maxPrev = pos > neg ? pos : neg;
        const newPos = maxPrev + x;
        const newNeg = pos - x;
        pos = newPos;
        neg = newNeg;
    }
    return Number(pos > neg ? pos : neg);
};
